rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM review_job WHERE cancellation_reason='NO_SANDBOX_ROOM') THEN
        RAISE EXCEPTION 'Cannot remove a cancellation reason used by existing review jobs. Restore a verified backup instead.';
    END IF;
END $$;
ALTER TABLE review_job DROP CONSTRAINT ck_review_job_cancellation;
ALTER TABLE review_job ADD CONSTRAINT ck_review_job_cancellation CHECK(cancellation_reason IS NULL OR cancellation_reason IN ('DRAIN_GRACEFUL','DRAIN_IMMEDIATE','BUDGET_EXHAUSTED','MODEL_UNAVAILABLE','MEMBER_AI_DECLINED','PERSON_DATA_ERASED','CANCELLED_BY_ADMIN','CANCELLED_BY_REQUESTER','CONTRACT_CHANGED'));

DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM review WHERE stop_reason='NO_SANDBOX_ROOM') THEN
        RAISE EXCEPTION 'Cannot remove a stop reason used by existing reviews. Restore a verified backup instead.';
    END IF;
END $$;
ALTER TABLE review DROP CONSTRAINT ck_review_stop_reason;
ALTER TABLE review ADD CONSTRAINT ck_review_stop_reason CHECK(stop_reason IS NULL OR stop_reason IN ('TIMED_OUT','EXECUTION_FAILED','PREPARATION_FAILED','PROCESSING_FAILED','PERSON_DATA_ERASED','STALE_ROLLOUT_REVISION','CANCELLED_BY_ADMIN','REPLACED','LEGACY_FAILURE','EXECUTION_INCOMPLETE','RESULT_WITHHELD','READINESS_REFUSED','SUSPECT_LISTING','BUDGET','USAGE_UNVERIFIABLE','DEADLINE','CANCELLED','ENUMERATION_FAILED','ENUMERATION_LIMIT','NO_SCAN_PRACTICES','MODEL_CHANGED','MODEL_UNAVAILABLE','ERROR','LEGACY_SCOPE_UNKNOWN','CONTRACT_CHANGED'));
